describe("session search interactions", () => {
  function setup() {
    const events = new EventTarget();
    const frames = new Map<number, FrameRequestCallback>();
    let nextFrame = 0;
    const schedule = (callback: FrameRequestCallback) => {
      frames.set(++nextFrame, callback);
      return nextFrame;
    };
    const cancel = (id: number) => frames.delete(id);
    class FocusElement {
      isConnected = true;
      focus = vi.fn();
      select = vi.fn();
    }
    const previousFocus = new FocusElement();
    const input = new FocusElement();
    const nextButton = new FocusElement();
    const testDocument = {
      activeElement: previousFocus,
      documentElement: { classList: { contains: () => false } },
      addEventListener: events.addEventListener.bind(events),
      removeEventListener: events.removeEventListener.bind(events),
    };
    input.focus.mockImplementation(() => {
      testDocument.activeElement = input;
    });
    nextButton.focus.mockImplementation(() => {
      testDocument.activeElement = nextButton;
    });
    const container = { contains: (node: unknown) => node === input || node === nextButton };
    class TestElement {
      nodeType = 1;
    }
    vi.stubGlobal("Element", TestElement);
    vi.stubGlobal("localStorage", {
      getItem: () => null,
      setItem: () => {},
      removeItem: () => {},
      clear: () => {},
    });
    vi.stubGlobal("HTMLElement", FocusElement);
    vi.stubGlobal("IS_REACT_ACT_ENVIRONMENT", true);
    vi.stubGlobal("requestAnimationFrame", schedule);
    vi.stubGlobal("cancelAnimationFrame", cancel);
    vi.stubGlobal("window", {
      matchMedia,
      Element: TestElement,
      HTMLElement: FocusElement,
      localStorage,
      addEventListener: events.addEventListener.bind(events),
      removeEventListener: events.removeEventListener.bind(events),
      dispatchEvent: events.dispatchEvent.bind(events),
      requestAnimationFrame: schedule,
      cancelAnimationFrame: cancel,
    });
    vi.stubGlobal("document", testDocument);
    const props = buildProps();
    const scrollToIndex = vi.fn();
    const list: Partial<LegendListRef> = {
      getState: vi.fn(),
      getScrollableNode: vi.fn(),
      scrollToIndex,
    };
    props.listRef.current = list as LegendListRef;
    return {
      props,
      input,
      nextButton,
      previousFocus,
      scrollToIndex,
      createNodeMock: (element: { type: unknown; props: unknown }) => {
        if (typeof element.props !== "object" || element.props === null) return null;
        if ("aria-label" in element.props && element.props["aria-label"] === "Search in thread")
          return input;
        if ("role" in element.props && element.props.role === "search") return container;
        return null;
      },
      flush: () =>
        act(() => {
          const pending = [...frames.values()];
          frames.clear();
          pending.forEach((callback) => callback(0));
        }),
    };
  }

  it("dismisses and clears search from a focused navigation button without intercepting Enter", async () => {
    const test = setup();
    let renderer: ReactTestRenderer | undefined;
    try {
      await act(() => {
        renderer = create(
          <MessagesTimeline
            {...test.props}
            timelineEntries={[buildUserTimelineEntry(buildLongUserMessageText("needle needle"))]}
          />,
          { createNodeMock: test.createNodeMock },
        );
      });
      act(() => {
        openSessionSearch(test.props.routeThreadKey);
      });
      act(() =>
        renderer!.root.findByProps({ "aria-label": "Search in thread" }).props.onChange({
          target: { value: "needle" },
        }),
      );
      act(() => {
        test.nextButton.focus();
        renderer!.root.findByProps({ "aria-label": "Next match" }).props.onClick();
      });
      expect(renderer!.root.findByProps({ role: "status" }).children).toEqual(["2 of 2"]);
      const event = {
        key: "Enter",
        keyCode: 13,
        shiftKey: false,
        nativeEvent: { isComposing: false },
        preventDefault: vi.fn(),
        stopPropagation: vi.fn(),
      };
      act(() => renderer!.root.findByProps({ role: "search" }).props.onKeyDown(event));
      expect(renderer!.root.findByProps({ role: "status" }).children).toEqual(["2 of 2"]);
      expect(event.preventDefault).not.toHaveBeenCalled();
      act(() =>
        renderer!.root.findByProps({ role: "search" }).props.onKeyDown({
          ...event,
          key: "Escape",
          keyCode: 27,
        }),
      );
      await test.flush();
      expect(renderer!.root.findAllByProps({ role: "search" })).toHaveLength(0);
      expect(test.previousFocus.focus).toHaveBeenCalled();
      act(() => {
        openSessionSearch(test.props.routeThreadKey);
      });
      expect(renderer!.root.findByProps({ "aria-label": "Search in thread" }).props.value).toBe("");
      expect(renderer!.root.findByProps({ role: "status" }).children).toEqual(["Type to search"]);
    } finally {
      act(() => renderer?.unmount());
      vi.unstubAllGlobals();
    }
  });

  it("opens the scoped search, reveals a collapsed user match, wraps, and loads history only on demand", async () => {
    const test = setup();
    const onLoadEarlier = vi.fn();
    const onManualNavigation = vi.fn();
    let renderer: ReactTestRenderer | undefined;
    try {
      await act(() => {
        renderer = create(
          <MessagesTimeline
            {...test.props}
            onManualNavigation={onManualNavigation}
            timelineEntries={[buildUserTimelineEntry(buildLongUserMessageText("needle needle"))]}
            loadEarlier={{ loading: false, cursor: "older", onLoadEarlier }}
          />,
          { createNodeMock: test.createNodeMock },
        );
      });
      expect(
        renderer!.root.findByProps({ "data-user-message-body": "true" }).props[
          "data-user-message-collapsed"
        ],
      ).toBe("true");
      act(() => {
        expect(openSessionSearch("other-environment:thread-1")).toBe(false);
      });
      expect(renderer!.root.findAllByProps({ role: "search" })).toHaveLength(0);
      act(() => {
        expect(openSessionSearch(test.props.routeThreadKey)).toBe(true);
      });
      expect(test.input.focus).toHaveBeenCalled();
      act(() =>
        renderer!.root
          .findByProps({ "aria-label": "Search in thread" })
          .props.onChange({ target: { value: "needle" } }),
      );
      expect(renderer!.root.findByProps({ role: "status" }).children).toEqual(["1 of 2"]);
      expect(
        renderer!.root.findByProps({ "data-user-message-body": "true" }).props[
          "data-user-message-collapsed"
        ],
      ).toBe("false");
      expect(onLoadEarlier).not.toHaveBeenCalled();
      await test.flush();
      expect(test.scrollToIndex).toHaveBeenLastCalledWith({
        index: 0,
        animated: false,
        viewOffset: 56,
      });
      const focusCalls = test.input.focus.mock.calls.length;
      act(() => {
        openSessionSearch(test.props.routeThreadKey);
      });
      expect(test.input.focus.mock.calls.length).toBeGreaterThan(focusCalls);
      expect(renderer!.root.findByProps({ "aria-label": "Search in thread" }).props.value).toBe(
        "needle",
      );
      act(() => renderer!.root.findByProps({ "aria-label": "Previous match" }).props.onClick());
      expect(renderer!.root.findByProps({ role: "status" }).children).toEqual(["2 of 2"]);
      act(() => renderer!.root.findByProps({ "aria-label": "Next match" }).props.onClick());
      expect(renderer!.root.findByProps({ role: "status" }).children).toEqual(["1 of 2"]);
      act(() =>
        renderer!.root
          .findByProps({ "aria-label": "Load earlier turns to include them in search" })
          .props.onClick(),
      );
      expect(onLoadEarlier).toHaveBeenCalledOnce();
      const callsBeforeClose = test.scrollToIndex.mock.calls.length;
      act(() => renderer!.root.findByProps({ "aria-label": "Close search" }).props.onClick());
      await test.flush();
      expect(test.scrollToIndex).toHaveBeenCalledTimes(callsBeforeClose);
      expect(renderer!.root.findAllByProps({ role: "search" })).toHaveLength(0);
      expect(
        renderer!.root.findByProps({ "data-user-message-body": "true" }).props[
          "data-user-message-collapsed"
        ],
      ).toBe("true");
      expect(test.previousFocus.focus).toHaveBeenCalled();
      expect(onManualNavigation).toHaveBeenCalled();
    } finally {
      act(() => renderer?.unmount());
      vi.unstubAllGlobals();
    }
  });

  it("gives new citation navigation priority and does not restore focus over another control", async () => {
    const test = setup();
    let renderer: ReactTestRenderer | undefined;
    const entry = buildUserTimelineEntry("needle");
    try {
      act(() => {
        renderer = create(<MessagesTimeline {...test.props} timelineEntries={[entry]} />, {
          createNodeMock: test.createNodeMock,
        });
      });
      act(() => {
        openSessionSearch(test.props.routeThreadKey);
      });
      act(() =>
        renderer!.root
          .findByProps({ "aria-label": "Search in thread" })
          .props.onChange({ target: { value: "needle" } }),
      );
      Object.defineProperty(document, "activeElement", { value: {}, configurable: true });
      act(() =>
        renderer!.update(
          <MessagesTimeline
            {...test.props}
            timelineEntries={[entry]}
            citationRequest={{
              key: "new-citation",
              citation: {
                version: 1,
                environmentId: ACTIVE_THREAD_ENVIRONMENT_ID,
                threadId: ThreadId.make("thread-1"),
                messageId: MessageId.make("cited-message"),
                text: "quoted",
                start: 0,
                end: 6,
                prefix: "",
                suffix: "",
              },
            }}
          />,
        ),
      );
      await test.flush();
      expect(renderer!.root.findAllByProps({ role: "search" })).toHaveLength(0);
      expect(test.scrollToIndex).not.toHaveBeenCalled();
      expect(test.previousFocus.focus).not.toHaveBeenCalled();
      act(() => {
        expect(openSessionSearch(test.props.routeThreadKey)).toBe(true);
      });
      expect(renderer!.root.findByProps({ "aria-label": "Search in thread" }).props.value).toBe("");
    } finally {
      act(() => renderer?.unmount());
      vi.unstubAllGlobals();
    }
  });

  it("cancels pending reveals during a held-thread transition and isolates identical thread IDs across environments", async () => {
    const test = setup();
    let renderer: ReactTestRenderer | undefined;
    const render = (threadKey: string, allowSessionSearch = true) => (
      <MessagesTimeline
        {...test.props}
        routeThreadKey={threadKey}
        displayThreadKey={threadKey}
        allowSessionSearch={allowSessionSearch}
        timelineEntries={[buildUserTimelineEntry("needle")]}
      />
    );
    try {
      act(() => {
        renderer = create(render(test.props.routeThreadKey), {
          createNodeMock: test.createNodeMock,
        });
      });
      act(() => {
        openSessionSearch(test.props.routeThreadKey);
      });
      act(() =>
        renderer!.root
          .findByProps({ "aria-label": "Search in thread" })
          .props.onChange({ target: { value: "needle" } }),
      );
      act(() => renderer!.update(render(test.props.routeThreadKey, false)));
      await test.flush();
      expect(test.scrollToIndex).not.toHaveBeenCalled();
      expect(renderer!.root.findAllByProps({ role: "search" })).toHaveLength(0);
      act(() => {
        expect(openSessionSearch(test.props.routeThreadKey)).toBe(false);
      });
      act(() => renderer!.update(render("remote:thread-1")));
      act(() => {
        expect(openSessionSearch(test.props.routeThreadKey)).toBe(false);
      });
      act(() => {
        expect(openSessionSearch("remote:thread-1")).toBe(true);
      });
      expect(renderer!.root.findByProps({ "aria-label": "Search in thread" }).props.value).toBe("");
      expect(renderer!.root.findByProps({ role: "status" }).children).toEqual(["Type to search"]);
    } finally {
      act(() => renderer?.unmount());
      vi.unstubAllGlobals();
    }
  });
});

import { ChevronDownIcon, ChevronUpIcon, XIcon } from "lucide-react";
import { memo, useCallback, useEffect, useLayoutEffect, useRef } from "react";

import { handleSessionSearchKeyDown, SESSION_SEARCH_MAX_QUERY_LENGTH } from "./sessionSearch";

export interface SessionSearchBarProps {
  readonly query: string;
  readonly onQueryChange: (query: string) => void;
  readonly matchCount: number;
  readonly currentMatchIndex: number;
  readonly focusRequestId: number;
  readonly onNext: () => void;
  readonly onPrevious: () => void;
  readonly onClose: () => void;
  readonly hasUnloadedHistory: boolean;
  readonly loadingEarlierHistory: boolean;
  readonly onLoadEarlierHistory?: (() => void) | undefined;
}

export const SessionSearchBar = memo(function SessionSearchBar(props: SessionSearchBarProps) {
  const inputRef = useRef<HTMLInputElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const restoreFocusRef = useRef<HTMLElement | null>(null);

  useLayoutEffect(() => {
    const container = containerRef.current;
    restoreFocusRef.current =
      document.activeElement instanceof HTMLElement ? document.activeElement : null;
    inputRef.current?.focus({ preventScroll: true });
    inputRef.current?.select();
    return () => {
      const restoreTarget = restoreFocusRef.current;
      if (
        restoreTarget?.isConnected &&
        (document.activeElement === document.body || container?.contains(document.activeElement))
      ) {
        restoreTarget.focus({ preventScroll: true });
      }
    };
  }, []);

  useEffect(() => {
    if (props.focusRequestId === 0) return;
    inputRef.current?.focus({ preventScroll: true });
    inputRef.current?.select();
  }, [props.focusRequestId]);

  const handleKeyDown = useCallback(
    (event: React.KeyboardEvent<HTMLElement>) => {
      handleSessionSearchKeyDown(event, {
        close: props.onClose,
        next: props.onNext,
        previous: props.onPrevious,
      });
    },
    [props],
  );

  const hasQuery = props.query.trim().length > 0;
  const resultLabel =
    hasQuery && props.matchCount > 0
      ? `${props.currentMatchIndex + 1} of ${props.matchCount}`
      : hasQuery
        ? "No matches"
        : "Type to search";

  return (
    <div
      ref={containerRef}
      role="search"
      aria-label="Search current thread"
      onKeyDown={(event) => {
        if (event.key === "Escape") handleKeyDown(event);
      }}
      className="absolute top-2 right-3 left-3 z-40 flex max-w-full flex-wrap items-center justify-end gap-1 rounded-lg border bg-popover px-2 py-1.5 shadow-lg sm:left-auto"
    >
      <input
        ref={inputRef}
        type="search"
        className="h-6 min-w-36 flex-1 bg-transparent text-sm text-foreground outline-none placeholder:text-muted-foreground/50 sm:w-52 sm:flex-none"
        placeholder="Search loaded turns..."
        value={props.query}
        maxLength={SESSION_SEARCH_MAX_QUERY_LENGTH}
        onChange={(event) => props.onQueryChange(event.target.value)}
        onKeyDown={handleKeyDown}
        aria-label="Search in thread"
      />
      <span
        role="status"
        aria-live="polite"
        className="shrink-0 text-xs text-muted-foreground/70 tabular-nums"
      >
        {resultLabel}
      </span>
      {props.hasUnloadedHistory && props.onLoadEarlierHistory ? (
        <button
          type="button"
          className="h-6 shrink-0 rounded px-1.5 text-xs text-muted-foreground/70 transition-colors hover:bg-accent/40 hover:text-foreground disabled:cursor-default disabled:opacity-50"
          onClick={props.onLoadEarlierHistory}
          disabled={props.loadingEarlierHistory}
          aria-label="Load earlier turns to include them in search"
        >
          {props.loadingEarlierHistory ? "Loading…" : "Load earlier"}
        </button>
      ) : null}
      <button
        type="button"
        className="flex size-6 items-center justify-center rounded text-muted-foreground/70 transition-colors hover:bg-accent/40 hover:text-foreground disabled:opacity-30"
        onClick={props.onPrevious}
        disabled={props.matchCount === 0}
        aria-label="Previous match"
      >
        <ChevronUpIcon className="size-3.5" />
      </button>
      <button
        type="button"
        className="flex size-6 items-center justify-center rounded text-muted-foreground/70 transition-colors hover:bg-accent/40 hover:text-foreground disabled:opacity-30"
        onClick={props.onNext}
        disabled={props.matchCount === 0}
        aria-label="Next match"
      >
        <ChevronDownIcon className="size-3.5" />
      </button>
      <button
        type="button"
        className="flex size-6 items-center justify-center rounded text-muted-foreground/70 transition-colors hover:bg-accent/40 hover:text-foreground"
        onClick={props.onClose}
        aria-label="Close search"
      >
        <XIcon className="size-3.5" />
      </button>
      {props.hasUnloadedHistory ? (
        <span className="w-full text-right text-[10px] leading-none text-muted-foreground/60">
          Results include loaded turns only
        </span>
      ) : null}
    </div>
  );
});
